说实话我有点受不了这种算账方式。想看真正精品的都得加钱，那普通票看的是啥？这不就是把好东西都藏起来当盲盒卖嘛。这年头，连看一眼千年前的佛像，都得先掂量掂量自己钱包厚不厚。

景区护文物要成本，能理解。可把文化弄成层层加码的生意，吃相就难看了。

