有人说郑晓龙犟，我看他是狠。
别人忙着找流量搏收视，他偏按军人的标准选演员。说白了，这剧讲大国重器的故事，要是找个偶像派在那挤眉弄眼，那不叫拍戏，叫砸招牌。

