          heat: "781.3万",
          content: `伦纳德百分大战定档，对手是白晶。
之前白晶和保罗·乔治打过，输了41分。
这回换成伦纳德，偏偏对手还是同一个草根球员。

咱们得先明白一件事：白晶不是没被打爆过，而是被打爆之后还敢接着约。
说白了，这就是草根的底气——输给超级巨星不丢人，丢的是连场都不敢上。我敢说，伦纳德就算只出七成力，白晶照样扛不住，但他敢站上去，就已经赢了99%嘴炮选手。

这年头，敢和真神较劲的，比真神本身更让人佩服。你们觉得白晶能咬住比分吗？`
