满场的镜头都追着大咖拍，偏偏她领完奖，安安静静自己往后门溜。

你刷到那张图的时候，估计也愣了一下——这年头拿奖的明星不趁机发通稿、不摆拍，反而像个路人抱着奖杯走了，太反常了。

说实话，比起那些感言念到一半就开始带货的，她这股“事了拂衣去”的劲儿，反而更让人记得住。我敢说，真正的体面从来不是人多势众，是一个人也能站得稳。

这年头，娱乐圈最缺的不是流量，是这种不抢镜的清醒。
