          heat: "46.9万",
          content: `不是她唱功不行了，也不是台语歌没人听了，而是陈盈洁这一辈子，最狠的那刀从来不在舞台上。

你肯定不爱听这种话，但有些人活着的时候就被辜负透了，走的时候反倒像解脱。1986年她23岁，恋上歌手潘健。结果呢？对方生意失败，人悄没声走了，丢下一屁股债让她扛。

我就直说了：一个男人能留给你最大的礼物，就是让你看清你一个人也能活。她后来能唱那么多年，骨子里那股狠劲，全是委屈喂出来的。

这年头，有些债不是钱还的，是用命熬的。她熬完了。

你觉得潘健这辈子，欠陈盈洁的一句对不起还上了吗？`
