你还在替她算奖杯账，她又把洛迦诺影后拿下了。说实话，金敏喜拿奖我一点都不意外，这女人早就不需要用韩剧甜妹那套证明自己了。洪尚秀镜头里的她，从来不是漂漂亮亮摆姿态，而是真敢把自己交出去。
结果呢，韩流还在卷红毯、卷代言、卷热搜，她拎着奖杯绕开一片骂声，继续拍她的文艺片。说白了，这个圈子里靠争议活着的人很多，能靠作品把争议踩在脚下的人太少。
我敢说，比起她的奖，更让一些人坐不住的是她过得根本不在乎。
这年头，作品硬气的人，连被骂都像在给下一次封后铺路。
