          content: `RED广州演唱会，765.8万热度压着一堆一线歌手往上冲，结果场馆还没坐满。

你没看错，热度和上座率这次彻底分了家。

一边是榜单上数字飙得飞起，一边是现场空着的座位被拍下来满屏转。数据不会骗人，但数据也最容易被当成遮羞布。

说白了，现在有些演唱会的"火"，火在热榜不在现场。歌迷用脚投票最诚实——你歌单里循环十遍，不代表你真愿意请假花钱坐两小时高铁去听现场。

这年头，虚的热度像泡沫，戳一下就破；能让人真掏钱买票的，永远是那些唱进心里的歌。

你们觉得，热度破千万和上座率爆满，哪个才算真红？`,
