          content: `蓝盈莹和曹骏三年恋情，分手后互祝成团。  
别人散了就拉黑，他们散了还点赞转发。  
可当她笑着说出“这次见了家长”，我才懂体面不是不痛，而是把真心收进礼数里。  
你品品——这年头，能笑着把旧爱变成战友的人，早把情绪管理练成了肌肉记忆。  
说白了，她不是突然开窍，是早把“恋爱”和“人生”分得清清楚楚：一个用来心动，一个用来扎根。  
我敢说，内娱真没几个人能把分手后的尊重，过成日常的呼吸感。  
这年头，肯为感情留体面的人，比热搜上的情话值钱多了。  
你们觉得，这种“不撕不炒不卖惨”的清醒，还能在圈里走多远？`
