        {
          id: 242,
          topic: "《绿灯军团》剧集发布预告 星际警察地球探案",
          source: "新浪电视",
          category: "娱乐热点",
          heat: "娱乐热点",
          content: `《绿灯军团》预告一出，我愣了三秒。（第1行）  
说好的宇宙级光能戒指、情感光谱、欧阿星议会呢？（第2行）  
结果开场就是主角蹲在朝阳区派出所做笔录，制服没穿齐，绿灯戒指还卡在保温杯盖上。（第3行）  
你敢信？这年头连星际警察都得来地球考编！  
咱们追了二十年DC动画和电影，谁不是冲着“意志力即力量”的热血设定去的？可现在——绿灯侠不飞了，改查监控；不制裁罪犯，先填《跨星域协查函》电子表单。  
说白了，不是特效没钱，是编剧怕观众看不懂“情感光谱”比“社保缴纳记录”更难理解。  
这年头，连外星人都得适应咱的基层治理节奏，真不是科幻，是纪实文学。  
你们觉得，当绿灯戒指亮起时，第一句该喊“以意志之名”，还是“请出示健康宝”？`
        },
        {
          id: 243,
          topic: "NCT辰乐出演天津泡泡岛音乐节 中文特辑舞台首唱",
          source: "新浪电视",
          category: "娱乐热点",
          heat: "娱乐热点",
          content: `辰乐开口唱中文那刻，我手机直接滑落三次。  
不是因为高音稳，也不是因为舞步齐，而是他咬字时喉结一颤——像在替所有海外长大的孩子，把没说出口的“妈，我会说”咽成气声。  
台下举着“辰乐中文好棒”的灯牌，可没人看见他后台练声视频里，录音笔旁摊开的《现代汉语词典》第7版……  
你有没有发现，我们总在夸“外国人学中文真厉害”，却从不问他们为了一句“我想你了”反复录过多少遍？  
说白了，这不是一场演出，是他把童年缺失的母语课，当着几万人的面补上了。  
这年头，能把乡音唱成铠甲的人，比靠滤镜活着的偶像值钱一百倍。  
你们觉得，他下次唱《茉莉花》时，会不会把苏州评弹的润腔偷偷加进去？`
        }
