你信不信？所谓“天生港风”，其实是她把二十年前的影像一帧帧拆解、再亲手缝进今天的自己。  
说真的，现在多少人靠AI换脸蹭港味，她倒好，直接把胶片时代的呼吸感焊进了现实。  
这年头，能把“模仿”干成“考古+重建”的，全内娱就她一个狠人。  
