          topic: "剧版《双城记》发布预告 经典故事传奇再述",
          source: "新浪电视",
          category: "娱乐热点",
          heat: "娱乐热点",
          content: `《双城记》这部小说，被搬上银幕和舞台的次数，早就多到数不清了。
可翻了下资料才发现，真正把它当"双城对照"拍出味道的，其实没几版——大多盯着爱情线跑，把法国大革命的背景拍成了布景板。
这回剧版预告打出口号"传奇再述"，我倒有点期待：终于有人想啃那层时代骨架了。
现在多少经典改编，懒得碰厚重历史，只敢蹭个名字做年轻化外壳。
偏偏《双城记》最值钱的，恰恰是那句"这是最好的时代，也是最坏的时代"背后的撕裂感。
能把两个城市的命运对照拍明白，比换十张漂亮脸蛋都重要。
你们觉得，这版能跳出"借壳恋爱"的老套路吗？`
