本以为又是套路化的甜宠模板，谁知它把“演着演着动了心”拍得格外较真。
可你想想，现在多少青春片只敢停在搂搂抱抱，它偏要正面刚“爱要不要承认”的拉扯。
真正打动人的从来不是告白多华丽，是两个人从试探到交付的那点真。
这种把青涩心事拍透的片，才是校园剧该有的样子。
