你真信她胖是黄瓜的锅？咱们早被“显瘦即努力、发福即懈怠”的镜头霸权PUA透了。  

她不是吃啥都胖，是镜头永远在挑刺——别人素颜出镜叫真实，她一松懈就被写成“状态下滑”。  

