说真的，现在观众早腻了苦练十年只为等一个爆点的悲情叙事——栾念偏用十年冷板凳，熬出了一张让全网破防的“该死的好看”。  
这年头，不争不抢的长相杀，才是对流量逻辑最体面的耳光。  
