          category: "娱乐热点",
          heat: "8699771",
          content: `王茜说，拍《重案六组》前，我在刑警队跟班三个月。  
每天蹲审讯室、摸枪套、抄笔录，连警服褶子都记熟了。  
结果现在翻出老剧截图，弹幕第一句还是“这哪是演的，这是季洁本人回岗了”。  

“还我季洁”不只是嘴上喊喊，那是观众在替一个被时代快进键跳过的专业主义鞠躬。  

当年王茜不是在演警察，她是把警徽别进了骨头缝里——别人演角色，她把自己拆了重装成季洁。  

现在不少“飒姐”靠滤镜撑人设，而王茜那会儿，是拿真实汗味和凌晨三点的卷宗堆出来的底气。  

这年头，能把职业尊严演成信仰的人，早比剧本还稀有。  

你们说，如果今天再拍《重案六组》，谁敢说一句“我先去派出所实习半年”？`
